import test from 'node:test';
import assert from 'node:assert/strict';
import {correctProductData} from './product-title-corrections.mjs';
const rows=[{id:'6kC1jJj7i4kRtYyp3SZr',titulo:'Patinete Elétrico Ydtech M187 Dobrável com Bluetooth',listing:'MLB7389762032'},{id:'6NYYO2l4QTGUagl47PKh',titulo:'Prancha Lizze Profissional 480 Extreme'}];
test('triagem55 exige identidade e preserva operação e afiliados com idempotência',()=>{for(const r of rows){const p={...r,preco:'99,99',linkAfiliado:'https://meli.la/preservado',variation_id:'original'},x=correctProductData(p);for(const k of Object.keys(p))assert.equal(x[k],p[k]);assert.deepEqual(correctProductData(x),x);for(const alt of [{titulo:'Capa para '+r.titulo},{id:'outro'},...(r.listing?[{link:'https://www.mercadolivre.com.br/p/MLB12345678?wid=MLB9999999999'}]:[])])assert.equal(correctProductData({...p,comentario:'preservar',...alt}).comentario,'preservar');}});
test('Ydtech não garante freios pneus desempenho ou aceitação no transporte',()=>{const x=correctProductData(rows[0]);assert.match(x.comentario,/não foram confirmados nesta revisão/);assert.match(x.comentario,/Não prometemos estabilidade, ausência de furos/);assert.match(x.comentario,/não confirma autorização de uso/);assert.doesNotMatch(x.pros,/E-ABS|12,5|450|estabilidade|sem furos|metrô|ônibus|limpo|autonomia/i);});
test('Lizze diferencia unidade de temperatura e não recomenda ajuste universal',()=>{const x=correctProductData(rows[1]);assert.match(x.comentario,/não significa 480 °C/);assert.match(x.comentario,/não recomendação de ajuste para qualquer cabelo/);assert.match(x.comentario,/sem presumir bivolt/);assert.doesNotMatch(x.pros,/todos os tipos|sem dano|garant|bivolt|frizz|uniforme/i);});
test('rádio fica sem alteração específica por falta de defeito demonstrado',()=>{const p={id:'6CiOb7YKL9YmF8Sqg1wT',titulo:'Rádio Am Fm Retrô Antigo Bluetooth Recarregável Bivolt Azul',comentario:'Texto da oferta preservado'},x=correctProductData(p);for(const k of Object.keys(p))assert.equal(x[k],p[k]);});
